# Let me check what values appear that ALSO are in same-value rows
# Same-value rows have values: 5, 4, 9
grid = [
    [5, 5], [5, 7], [9, 4], [4, 4],
    [7, 2], [2, 6], [9, 2], [2, 7],
    [2, 8], [5, 2], [7, 9], [9, 1],
    [6, 9], [9, 9]
]

same_values = {5, 4, 9}
print(f"Same-value row values: {sorted(same_values)}")

# For each row, if col0 or col1 is in same_values, use that as the answer
# If neither, what then? Maybe output [col0, col0] or [col1, col1]?

print("\n=== Row analysis ===")
for i, (a, b) in enumerate(grid):
    values_in_row = {a, b}
    intersect = values_in_row & same_values
    print(f"Row {i}: {grid[i]}, intersect={intersect}")

# Hypothesis: for each row, output = [v, v] where v is the value in the row that's in same_values
# If both are in same_values, output [first or second]?
def transform_row(a, b):
    if a in same_values:
        return (a, a)
    elif b in same_values:
        return (b, b)
    else:
        return (a, a)

# Test this
result = [transform_row(a, b) for a, b in grid]
print("\nHypothesis: output same-value if this value exists in row:")
for row in result:
    print(row)

