    [5, 5], [5, 7], [9, 4], [4, 4],
    [7, 2], [2, 6], [9, 2], [2, 7],
    [2, 8], [5, 2], [7, 9], [9, 1],
    [6, 9], [9, 9]
]

same_values = {5, 4, 9}
most_freq_col0 = 9
most_freq_col1 = 2  # from earlier analysis

def transform_row(a, b):
    if a in same_values:
        return (a, a)
    elif b in same_values:
        return (b, b)
    else:
        # Fallback: use most frequent of that yardcast?
        return (most_freq_col0, most_freq_col0)  # all [9,9]

result = [transform_row(a, b) for a, b in grid]
print("Hypothesis: same-value preferred, fallback to [9,9]:")
for row in result:
    print(row)

# Alternatively, fallback to keeping as-is?
def transform2(a, b):
    if a in same_values:
        return (a, a)
    elif b in same_values:
        return (b, b)
    else:
        return (a, b)

result2 = [transform2(a, b) for a, b in grid]
print("\nHypothesis: same-value preferred, else unchanged:")
for row in result2:
    print(row)

# Try [9,9] as fallback for rows not containing 5, 4, or 9
